import { part as p, example, history, source, before, sample, s, op } from './authoring.mjs';
import { table, flow, challenge, q, tf } from './design-authoring.mjs';

function lesson(record) {
  const { checkpointAfter, checkpoint, technicalPart, ...rest } = record;
  const parts = record.parts.map((entry, i) => ({ ...entry, title: `${i + 1}. ${entry.title}` }));
  return { ...rest, section: 'Agents', parts, technicalStart: parts[technicalPart - 1].title, checkpoints: [{ after: parts[checkpointAfter - 1].title, title: `Questions on Parts 1 to ${checkpointAfter}`, questions: checkpoint }] };
}
const build = (title, problem, challenge, sources, cases, recipe, why, limitation, hints) => ({ title, problem, challenge, sources, cases, recipe, why, limitation, hints, extras: [], draftVersion: 1 });
const trial = (name, rank, passed, latency_ms, cost_units) => ({ name, rank, passed, latency_ms, cost_units });
const basicTrials = [trial('rules', 0, [true, false, false], [10, 12, 11], [0, 0, 0]), trial('workflow', 1, [true, true, true], [600, 800, 700], [2, 2, 2]), trial('agent', 2, [true, true, true], [1200, 1600, 1400], [5, 6, 5])];
const selectionPolicy = { min_passes: 3, max_latency_ms: 2000, max_cost_units: 20 };
const chooseSolution = `def choose_controller(candidates, policy):
    def whole(value):
        return type(value) is int and value >= 0
    if not isinstance(policy, dict) or any(not whole(policy.get(k)) for k in
            ("min_passes", "max_latency_ms", "max_cost_units")):
        raise ValueError("Invalid acceptance requirements")
    if not isinstance(candidates, list):
        raise ValueError("Candidates must be a list")
    eligible, names = [], set()
    case_count = None
    for row in candidates:
        if not isinstance(row, dict):
            raise ValueError("Each candidate needs named fields")
        name, rank = row.get("name"), row.get("rank")
        passed, times, costs = (row.get(k) for k in ("passed", "latency_ms", "cost_units"))
        if not isinstance(name, str) or not name.strip() or name in names or not whole(rank):
            raise ValueError("Invalid candidate identity")
        names.add(name)
        if not isinstance(passed, list) or not passed or any(type(v) is not bool for v in passed):
            raise ValueError("Provide boolean task results")
        if case_count is not None and len(passed) != case_count:
            raise ValueError("Use the same cases for every controller")
        case_count = len(passed)
        if any(not isinstance(values, list) or len(values) != case_count or
               any(not whole(v) for v in values) for values in (times, costs)):
            raise ValueError("Align nonnegative latency and cost measurements")
        total_cost = sum(costs)
        if (sum(passed) >= policy["min_passes"] and
                max(times) <= policy["max_latency_ms"] and
                total_cost <= policy["max_cost_units"]):
            eligible.append((rank, total_cost, name))
    return min(eligible)[2] if eligible else "review requirements"

trials = [
    {"name":"workflow", "rank":1, "passed":[True, False], "latency_ms":[300, 500], "cost_units":[2, 2]},
    {"name":"agent", "rank":2, "passed":[True, True], "latency_ms":[900, 1200], "cost_units":[4, 5]},
]
policy = {"min_passes":2, "max_latency_ms":1500, "max_cost_units":12}
print(choose_controller(trials, policy))`;

const architecture = lesson({
  id: 'agent-or-workflow', title: 'Does Botie Need to Choose the Next Step?', topic: 'Choosing How Much Autonomy to Give',
  blurb: 'A request to find a maintenance record and an investigation of an unfamiliar fault ask different things of the program. Compare what fixed steps can do before giving a model more decisions.',
  openingTitle: 'We Have Built a Tool Loop. Do We Need It for This Job?',
  opening: ['A technician asks for the inspection date of pump P7. We already know the steps: check access, look up P7, and display the date. Giving Botie freedom to invent a plan adds decisions to a job whose route we can write down ourselves.', 'Now consider a request to explain why several pumps began vibrating after a maintenance visit. The useful follow-up depends on what the records reveal. We need a way to decide where a model’s choice of next step actually helps. We will compare candidate controllers on the same invented maintenance requests, including their mistakes.'],
  prerequisites: [before('Tool contracts', 'agent-tool-contracts'), before('Agent loops', 'agent-loops')],
  history: history('Separating a Predetermined Route from a Model’s Choice', [source('Anthropic: Building effective agents, December 2024', 'https://www.anthropic.com/engineering/building-effective-agents'), source('Anthropic: How we built our multi-agent research system', 'https://www.anthropic.com/engineering/multi-agent-research-system')], 'Once language models could call tools, developers could give them control over a sequence of operations. That raised a practical question: which decisions should remain in ordinary application code? Anthropic’s December 2024 engineering article distinguished predefined workflows from systems in which a model chooses its next operations. It described patterns used in applications, rather than claiming to have invented workflows or software agents.', 'Think about the maintenance desk. Retrieving a known record already has a route. Investigating a poorly described fault may require looking at a result before deciding what to inspect next. Our examples use invented measurements to make that design choice visible. They are not benchmark results for any provider or framework.'),
  reading: { experimentTitle: 'Which controller meets the maintenance desk’s requirements?', experimentIntro: 'Keep the task checks beside each controller’s time and cost. Connect the comparison before choosing the amount of autonomy.', connectionTitle: 'Use evidence to decide who chooses the next operation', practiceTitle: 'Practice. Select a controller from its trial records', outputLabel: 'Selected controller', exampleNote: 'The trials are invented. This workshop compares records; it does not run a model or establish production reliability.' },
  intuition: [table('The same request can travel through different controllers', 'The route belongs to application code in a workflow. A model chooses the next operation in our agent candidate.', ['Request', 'Known steps', 'What could require another decision?'], [['When was P7 inspected?', 'Authorise → lookup → display date', 'Missing or inaccessible record has a defined error path'], ['Explain the new vibration', 'Start from the reported symptom', 'The next useful record depends on the evidence returned'] ], 'A workflow can contain a model call. Using a model does not automatically give it control of the route.'), table('Compare success before preferring fewer moving parts', 'Each candidate receives the same three fictional requests. Here the workflow already satisfies the task checks.', ['Controller', 'Task checks passed', 'Slowest observed request', 'Total invented cost units'], [['Rules', '1 of 3', '12 ms', '0'], ['Workflow', '3 of 3', '800 ms', '6'], ['Agent', '3 of 3', '1600 ms', '16']], 'This tiny fixture demonstrates the comparison. A maximum over three observations is not a production latency percentile.')],
  technicalPart: 5, checkpointAfter: 4,
  parts: [
    p('Write down what a completed maintenance request means', 'Start with the result the technician needs. For a record lookup, success means returning the correct authorised record or accurately reporting that it is unavailable. For an investigation, success may mean identifying relevant evidence and explaining what remains uncertain. A fluent response that omits the missing evidence does not complete that job.\n\nChoose the acceptance checks before trying architectures. Keep cases where a record is missing, where access is denied, and where two assets have similar names. If only the happy path appears in the test set, the most fragile controller can look convincing.', null, 'The checks describe the job. The controller is one proposal for doing it.'),
    p('Try the route we can already specify', 'A direct database lookup is a useful baseline for a date request. A baseline is a working comparison that tells us what extra machinery improves. It may be ordinary code, a search interface, or one model call with supplied evidence.\n\nA fixed workflow can validate a request, retrieve a manual, ask a model for a supported summary, then check its output. Branches for absent evidence and failed validation remain explicit. We can test each branch without asking a model to discover the order again. The wording step may still be uncertain, so fixed orchestration does not make the whole system deterministic.', null, 'Give the baseline a fair implementation. An intentionally weak prompt would make a larger architecture appear more useful than it is.'),
    p('Find the decision that depends on a previous result', 'Suppose the first maintenance record points to a replacement coupling. Botie might need the coupling specification next. A different record might point to a changed sensor. We can allow a model to choose among a limited set of read operations based on that evidence.\n\nThis creates a new responsibility: checking whether each proposed action is permitted and whether the investigation has enough evidence to stop. Tool feedback tells the loop what happened. A missing record can trigger a supported answer about uncertainty rather than another speculative query. Keep the earlier output and permission checks when adding this freedom.', null, 'Choose an agent because the task benefits from adaptive decisions. The presence of several tools alone does not establish that benefit.'),
    p('A second agent adds a handoff we must explain', 'Separate specialists can examine genuinely independent records in parallel. Before adding them, identify what each receives, what it must return, and who combines conflicting findings. A handoff should preserve the request identity and source IDs. The coordinator needs a way to recognise partial or failed work.\n\nSending the same full conversation to several agents repeats input work and introduces several proposals to reconcile. Parallel work can reduce elapsed time while increasing total compute. A copied mistake may appear in every answer, so agreement is not independent evidence. Begin with one controller and measure whether delegation improves the task enough to justify its coordination and operating costs.', null, 'For the maintenance desk, two independent manual searches may be useful. Two agents that both create the same work order introduce a different problem.'),
    p('Keep trial results aligned with their measurements', 'The workshop stores each controller as a dictionary. passed is a list of boolean outcomes in the agreed case order. latency_ms and cost_units have one entry for each of those same cases. rank records our declared preference for less autonomy: rules first, then workflow, then agent. A rank is a design policy, not a measure of intelligence.\n\nWe summarise how many checks passed, the slowest observed request, and total cost over the fixture. Comparing different case sets would confound architecture with task difficulty. Real evaluations should retain case IDs and versions, repeat stochastic runs, and report uncertain estimates. Our short list assumes that alignment has already been checked.', null, 'Latency and cost answer different questions. A parallel controller may have a smaller wall-clock maximum and a larger total bill.', [example('Read one controller’s aligned trial rows', 'zip pairs the values by position. Check equal lengths first so a missing measurement cannot disappear silently.', 'passed = [True, False, True]\nlatency_ms = [420, 510, 470]\ncost_units = [2, 3, 2]\nassert len(passed) == len(latency_ms) == len(cost_units)\nfor case, (ok, elapsed, cost) in enumerate(zip(passed, latency_ms, cost_units), start=1):\n    print(case, ok, elapsed, cost)\nprint("passes:", sum(passed))', '1 True 420 2\n2 False 510 3\n3 True 470 2\npasses: 2', 'The failed case remains in the measurements. Removing it would hide both the failure and the resources it consumed.')]),
    p('Apply requirements before choosing simplicity', 'Filter the summaries against the acceptance requirements. Our fixture requires every supplied task check to pass and bounds observed latency and total cost. Among candidates that meet those requirements, choose the lowest autonomy rank. If ranks tie, choose lower total cost, then the alphabetically earlier name so the result is repeatable.\n\nThis is an explicit teaching policy. A real service may prioritise tail latency, audit requirements, operating effort or a risk threshold differently. State that policy before looking at the candidate scores. If no candidate passes, return a review outcome. Quietly selecting the least bad failure would erase the meaning of the requirements.', 'eligible = task_passes >= required_passes\n           and worst_latency <= latency_limit\n           and total_cost <= cost_limit', 'Passing this fixture is permission to investigate a candidate further. It is not a guarantee about future requests.'),
    p('Let a new kind of fault challenge the chosen route', 'The changed workshop case gives the fixed workflow a request it cannot resolve. Its score now fails the task requirement, while the agent candidate meets the same requirements. Keep the selection policy unchanged and inspect which evidence changed the decision.\n\nA single adaptive example should not make every request autonomous. Routing well-defined requests through the simpler path and reserving an agent for measured difficult cases can be useful. The router needs its own evaluation, including false escalations and difficult requests it incorrectly keeps on the simple path.', null, 'The useful outcome is a design tied to task evidence, with a clear fallback when the evidence is insufficient.'),
    p('Keep the operating boundary when the controller changes', 'A workflow and an agent can use the same scoped read tool, output validator and human approval boundary. Changing who chooses the next step does not change who is authorised to read a customer’s records or create an inspection.\n\nVersion the controller along with prompts, tools, model settings and evaluation data. Re-run the comparison after a meaningful change. Watch the real request mix: a controller chosen for mostly date lookups may need reconsideration when most users begin asking open investigations. Frameworks in the next lessons can organise these components, but their abstractions should leave the decision boundaries visible.', null, 'We can now ask a more useful framework question: does it make the controller we chose easier to implement, test and inspect?'),
  ],
  checkpoint: [q('P7 lookup always follows access check → database lookup → response. A model formats the response but cannot choose another operation.', 'Which description fits this controller?', ['A workflow containing a model call', 'An agent that dynamically chooses every tool', 'A system that needs several agents because it uses a model'], 0, 'The application fixes the route. The model only performs its assigned wording step.'), tf('Two agents receive the same incorrect excerpt and independently repeat its claim.', 'Their agreement establishes that the claim is supported by correct evidence.', false, 'The common bad input can create correlated errors. Agreement does not repair its source.')],
  quiz: [q('Workflow and agent both pass all required cases. Workflow rank is 1 and total cost is 8. Agent rank is 2 and total cost is 6. Both satisfy the time and cost limits. Policy prefers lower rank before cost.', 'Which controller does this declared policy select?', ['Workflow', 'Agent', 'Neither because costs differ'], 0, 'The rank is compared first among eligible candidates. Cost breaks a tie at the same rank.'), tf('No candidate meets the minimum task requirement in the supplied trial records.', 'Returning review requirements preserves the fact that no candidate was accepted.', true, 'The selection function should not turn a failed requirement into a successful deployment decision.')],
  practice: [challenge('Which controller earns a trial at the maintenance desk?', ["The desk needs a controller that completes its required jobs within its operating limits. Give extra autonomy a trial only when the measured task calls for it. Write choose_controller(candidates, policy). Each candidate has unique nonblank name, nonnegative integer rank, nonempty boolean passed list, and equally long lists latency_ms and cost_units containing nonnegative integers. Every candidate uses the same case count and order. policy contains nonnegative integer min_passes, max_latency_ms and max_cost_units. Reject malformed input with ValueError; booleans are not valid integer measurements.","Keep candidates meeting all three requirements. Return the name with the smallest tuple (rank, total cost, name), or \"review requirements\" if none qualify. Do not mutate inputs. Print the result for the two supplied trial records."], 'def choose_controller(candidates, policy):\n    pass\n\ntrials = [\n    {"name":"workflow", "rank":1, "passed":[True, False], "latency_ms":[300, 500], "cost_units":[2, 2]},\n    {"name":"agent", "rank":2, "passed":[True, True], "latency_ms":[900, 1200], "cost_units":[4, 5]},\n]\npolicy = {"min_passes":2, "max_latency_ms":1500, "max_cost_units":12}\nprint(choose_controller(trials, policy))', chooseSolution, 'agent', ['Check list alignment before aggregating measurements.', 'Keep the acceptance filter separate from the ordering policy. min on a list of tuples follows the declared priority.'], [['Adaptive route passes the task', 'assert choose_controller(trials, policy) == "agent"'], ['Empty shortlist and exact limits', 'assert choose_controller([], policy) == "review requirements"\nassert choose_controller(trials, {**policy, "max_latency_ms":1199}) == "review requirements"\nassert choose_controller(trials, {**policy, "max_latency_ms":1200, "max_cost_units":9}) == "agent"'], ['Least autonomy before lower cost', 'import copy\nrows = copy.deepcopy(trials)\nrows[0]["passed"] = [True, True]\nrows[1]["cost_units"] = [0, 0]\nsnapshot = copy.deepcopy(rows)\nassert choose_controller(rows, policy) == "workflow"\nassert rows == snapshot'], ['Reject missing measurements and boolean counts', 'for rows, limits in [([{"name":"x", "rank":0, "passed":[True], "latency_ms":[], "cost_units":[1]}], policy), (trials, {**policy,"min_passes":True})]:\n    try:\n        choose_controller(rows, limits)\n    except ValueError:\n        pass\n    else:\n        raise AssertionError("Malformed records must be rejected")'], ['Stable tie policy', 'rows = [{"name":name,"rank":1,"passed":[True],"latency_ms":[10],"cost_units":[cost]} for name,cost in [("zeta",2),("beta",1),("alpha",1)]]\nassert choose_controller(rows, {"min_passes":1,"max_latency_ms":10,"max_cost_units":2}) == "alpha"']])],
  build: build('Choose how much control Botie needs', 'The maintenance desk has several controllers tested on the same requests. It needs one that meets its declared requirements.', 'Summarise the aligned trial records, filter by the requirements, and choose the least autonomy among the candidates that passed. Preserve review requirements when none pass.', { trials: 'Controllers tested on the same requests', policy: 'Task, time and cost requirements' }, [sample('The fixed workflow already does the job', { trials: basicTrials, policy: selectionPolicy }, 'workflow'), sample('A fault needs a result-dependent lookup', { trials: [basicTrials[0], { ...basicTrials[1], passed: [true, true, false] }, basicTrials[2]], policy: selectionPolicy }, 'agent'), sample('The time requirement excludes every usable controller', { trials: basicTrials, policy: { ...selectionPolicy, max_latency_ms: 500 } }, 'review requirements')], op('arChooseController', op('arEligibleControllers', op('arSummariseTrials', s('trials')), s('policy'))), 'Task evidence determines eligibility. The declared simplicity preference chooses among eligible controllers without hiding their measurements.', 'The small invented trial set is a teaching comparison. It omits repeated model runs, uncertainty intervals and production security review.', ['Start with the controller records. Each controller needs its own summary.', 'Keep the requirements filter before the final choice so a cheap failure cannot win.']),
});

const retrySchedule = { base_ms: 200, cap_ms: 1000, jitter_fraction: 0.5, timeout_ms: 500, max_attempts: 3 };
const retryClock = { attempts: 1, now_ms: 1000, deadline_ms: 2500 };
const operation = { key: 'R7-inspect-1', payload: { asset: 'P7', operation: 'inspect' }, effect: 'write', idempotent: true };
const recovery = (route, delay_ms = 0, result = null) => ({ route, delay_ms, result });
const retrySolution = `def next_action(command, receipts, outcome, schedule, state):
    def whole(value):
        return type(value) is int and value >= 0
    def same_payload(left, right):
        if isinstance(left, dict) and isinstance(right, dict):
            return left.keys() == right.keys() and all(same_payload(left[k], right[k]) for k in left)
        if isinstance(left, list) and isinstance(right, list):
            return len(left) == len(right) and all(same_payload(a, b) for a, b in zip(left, right))
        if type(left) in (int, float) and type(right) in (int, float):
            return left == right
        return type(left) is type(right) and left == right
    if (not isinstance(command, dict) or not isinstance(command.get("key"), str)
            or not command["key"].strip() or not isinstance(command.get("payload"), dict)
            or command.get("effect") not in ("read", "write")
            or type(command.get("idempotent")) is not bool):
        raise ValueError("Invalid operation")
    if outcome not in ("success", "transient", "permanent", "unknown"):
        raise ValueError("Invalid outcome")
    if not isinstance(schedule, dict) or not isinstance(state, dict):
        raise ValueError("Schedule and state must be records")
    if any(not whole(schedule.get(k)) for k in ("base_ms", "cap_ms", "timeout_ms", "max_attempts")) or schedule["timeout_ms"] == 0:
        raise ValueError("Invalid retry schedule")
    if any(not whole(state.get(k)) for k in ("attempts", "now_ms", "deadline_ms")):
        raise ValueError("Invalid run clock")
    jitter = schedule.get("jitter_fraction")
    if type(jitter) not in (int, float) or not 0 <= jitter <= 1:
        raise ValueError("Jitter fraction must be from zero to one")
    if not isinstance(receipts, list):
        raise ValueError("Receipts must be a list")
    found, keys = None, set()
    for row in receipts:
        if (not isinstance(row, dict) or not isinstance(row.get("key"), str)
                or not row["key"].strip() or row["key"] in keys
                or not isinstance(row.get("payload"), dict)
                or row.get("status") not in ("completed", "pending")
                or (row.get("status") == "completed" and "result" not in row)):
            raise ValueError("Invalid receipt ledger")
        keys.add(row["key"])
        if row["key"] == command["key"]:
            found = row
    def result(route, delay=0, value=None):
        return {"route":route, "delay_ms":delay, "result":value}
    if found is not None:
        if not same_payload(found["payload"], command["payload"]):
            return result("reject changed payload")
        if found["status"] == "completed":
            return result("return stored result", value=found.get("result"))
        return result("query operation status")
    if outcome == "success":
        return result("done")
    if outcome == "permanent":
        return result("repair request")
    if command["effect"] == "write" and not command["idempotent"]:
        return result("reconcile outcome")
    exponent = min(max(state["attempts"] - 1, 0), 52)
    delay = int(min(schedule["cap_ms"], schedule["base_ms"] * 2 ** exponent) * jitter)
    fits = (state["attempts"] < schedule["max_attempts"]
            and state["now_ms"] < state["deadline_ms"]
            and state["now_ms"] + delay + schedule["timeout_ms"] <= state["deadline_ms"])
    return result("retry same operation key", delay) if fits else result("stop at run limit")

command = {"key":"R9-inspect-1", "payload":{"asset":"P9","operation":"inspect"}, "effect":"write", "idempotent":True}
schedule = {"base_ms":300,"cap_ms":1200,"jitter_fraction":0.5,"timeout_ms":400,"max_attempts":4}
state = {"attempts":2,"now_ms":1000,"deadline_ms":2000}
print(next_action(command, [], "unknown", schedule, state))`;

const retries = lesson({
  id: 'agent-retries-and-effects', title: 'Did Botie Create the Inspection, or Did the Reply Get Lost?', topic: 'Keeping an Agent Run Under Control',
  blurb: 'A request times out after Botie submits an inspection. Work out what the service may already have done before sending another request.',
  openingTitle: 'One Approved Inspection Has Become Two Jobs',
  opening: ['The technician approves an inspection of P7. Botie submits the request, but the connection closes before the reply arrives. He tries again. The service now shows two inspection jobs for the same request.', 'From Botie’s side, the first attempt failed to produce a reply. From the service’s side, it may have succeeded. We need to keep those facts separate. This lesson builds a recovery decision that can reuse a recorded result, wait for a pending operation, or stop when another attempt would be unsafe.'],
  prerequisites: [before('Human approval', 'agent-human-approval'), before('State and replay with LangGraph', 'agent-langgraph')],
  history: history('A Lost Reply Was a Problem Before Models Called Tools', [source('Amazon Builders’ Library: Making retries safe with idempotent APIs', 'https://aws.amazon.com/builders-library/making-retries-safe-with-idempotent-APIs/'), source('Amazon Builders’ Library: Timeouts, retries, and backoff with jitter', 'https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/'), source('Stripe API: Idempotent requests', 'https://docs.stripe.com/api/idempotent_requests'), source('gRPC: Deadlines', 'https://grpc.io/docs/guides/deadlines/')], 'Distributed services have long faced the problem of a request whose effect succeeds while its reply is lost. Amazon’s Builders’ Library describes how client request identifiers let a service recognise repeated intent; its idempotent API article was announced in January 2021. An agent calling a work-order service inherits this same communication problem.', 'The practical idea is to give the intended inspection a stable identity. A repeated delivery of that operation can then recover its earlier result within the receiving service’s documented contract. Our receipt ledger is a teaching model. It does not implement a distributed transaction or promise that every request eventually succeeds.'),
  reading: { experimentTitle: 'What should happen after the missing reply?', experimentIntro: 'Keep the receipt lookup, retry safety and run deadline visible on separate branches. Then combine them into one recovery action.', connectionTitle: 'Recover an operation without inventing another one', practiceTitle: 'Practice. Decide the next recovery action', outputLabel: 'Recovery decision', exampleNote: 'No work-order service is called. Receipt records and clocks are supplied fixtures.' },
  intuition: [flow('A timeout describes the caller’s observation', 'The effect and the reply happen at different points. A broken connection can separate them.', [['Botie', 'Submit operation R7-inspect-1'], ['Work-order service', 'Create WO-41 and store the operation receipt'], ['Network', 'Reply is lost'], ['Botie', 'Sees a timeout; cannot infer that no work occurred']], 'The service receipt answers a question that the missing reply cannot.'), table('Look at what the receiver knows', 'Use the same operation key and compare the complete action payload.', ['Receipt state', 'Meaning', 'Recovery action'], [['Completed, same payload', 'The intended effect has a recorded result', 'Return that result'], ['Pending, same payload', 'Processing is already in progress', 'Query status within a bounded policy'], ['Same key, different payload', 'The caller changed the intended action', 'Reject the conflict'], ['No receipt', 'This snapshot contains no result', 'Apply retry safety and deadline checks']], 'An absent receipt is usable evidence only within the service’s consistency and idempotency contract.')],
  technicalPart: 4, checkpointAfter: 3,
  parts: [
    p('Classify the failure before choosing another attempt', 'A permission denial or invalid asset identifier will not improve because the same request is sent again. Route those permanent failures to repair or review. A temporary overload or interrupted connection may justify a retry, but the tool’s contract must establish whether repeating the operation is safe.\n\nKeep unknown outcomes distinct from known rejections. For a write, a timeout can mean the service completed the effect without delivering a reply. For a read, another request usually avoids duplicate business effects, though it still consumes resources and can return changed data. Our fixture labels outcomes success, transient, permanent or unknown; real adapters map their documented error codes into those categories.', null, 'The model does not get to reinterpret a permission denial as an invitation to try different arguments until something works.'),
    p('Give the intended operation an identity', 'Create an operation key when the application accepts the approved intent. Persist it before sending the write. Reuse it when delivering that same operation again. A genuinely new inspection needs a new key, even if its asset and other fields match an earlier inspection.\n\nThe receiver binds the key to the caller’s scope and the relevant payload. The same key with a different pump or schedule must be a conflict. Avoid relying on the model to invent or remember this identity. It belongs to application state alongside the approved action revision.', null, 'A key in a request header is only useful if the receiving service enforces the contract.'),
    p('Recover the receiver’s answer before scheduling more work', 'A completed receipt can return the earlier work-order ID. A pending receipt tells us the operation is already under way. A status query or a bounded wait is appropriate; launching a second operation is not.\n\nThis requires an authoritative ledger. A stale cache or an unavailable status endpoint cannot prove that the operation never happened. When the receiving service offers neither an idempotency contract nor a reliable reconciliation path, retain the ambiguous outcome for review. Do not turn it into an automatic new write. The workshop’s absent receipt assumes a trustworthy snapshot within the stated service contract.', null, 'Approval answers whether we may perform the action. A receipt answers what happened when we tried. Neither replaces the other.'),
    p('What the idempotency boundary has to store', 'The service needs a unique operation identity, a fingerprint or canonical representation of its payload, a processing state, and a stored result. Concurrent deliveries of the same operation must compete at an atomic boundary so both cannot decide they are the first.\n\nThe exact transaction depends on where the effect happens. A database write and its receipt may share a transaction. An external email or another service cannot automatically join that transaction; outbox delivery and downstream idempotency may be needed. Receipt retention also matters. Once a receiver forgets a key, a late replay may be treated as new work. Read the actual API contract and keep retries inside its scope and retention window.', null, 'Our Python dictionary lookup demonstrates the decision only. It is not a concurrency-safe store.', [example('Recover a known operation result', 'A dictionary indexed by operation key makes a completed receipt easy to find. This example performs no write.', 'receipts = {\n    "R4-inspect-1": {"asset":"P4", "status":"completed", "result":"WO-18"}\n}\nkey = "R4-inspect-1"\nreceipt = receipts.get(key)\nif receipt is not None and receipt["status"] == "completed":\n    print(receipt["result"])\nelse:\n    print("No completed receipt in this snapshot")', 'WO-18', 'The result belongs to the earlier operation. The full challenge will also reject a reused key whose payload changed.')]),
    p('Give every attempt a timeout and the whole run a deadline', 'A per-attempt timeout bounds how long the caller waits for one operation. A run deadline bounds the whole recovery process, including delays and repeated attempts. Starting a fresh timeout after each failure can otherwise keep the run alive far longer than intended.\n\nCount attempts that have actually started, including the first. Before scheduling another, check the remaining attempt allowance and whether its delay plus timeout fits the remaining deadline. Use a monotonic clock for elapsed-time accounting in a real process. Pass the remaining deadline to downstream calls where supported. Timing out locally does not roll back an effect already accepted elsewhere.', null, 'The supplied fixture clock is an integer millisecond counter so every branch can be tested without sleeping.'),
    p('Spread retries without letting them continue forever', 'Repeated immediate requests can worsen an overloaded service. Exponential backoff increases the upper delay after successive attempts, and a cap prevents unbounded waiting. Jitter chooses a delay within a range so many clients do not all retry at the same instant.\n\nOur full-jitter demonstration supplies a fraction between zero and one rather than drawing randomness during a test. We multiply that fraction by the capped upper delay and round down to whole milliseconds. In production, draw the random value per attempt and honour the service’s documented Retry-After guidance. Keep a separate total deadline; a capped delay alone allows infinitely many retries.', 'upper_delay = min(cap_ms, base_ms * 2 ** max(attempts_started - 1, 0))\ndelay_ms = floor(upper_delay * jitter_fraction)\nnext_attempt_fits = now_ms + delay_ms + timeout_ms <= deadline_ms', 'Equality is allowed in our scheduling fixture. Actual transport scheduling and cancellation are not precise guarantees that a remote operation finishes at that instant.'),
    p('Choose one place to own automatic recovery', 'A provider SDK may already retry a request. A framework may retry a model response that fails validation. A tool adapter may retry its service call. If each surrounding layer also repeats the whole operation, the actual number of requests can grow much faster than the visible loop count.\n\nInspect the layers and give each failure one deliberate recovery owner. Count transport attempts separately from model turns and tool proposals. Record the operation key, attempt number, error category and final outcome without leaking sensitive request bodies. A validation retry asks for corrected content; a transport retry resends delivery. They have different purposes and may consume different budgets.', null, 'An agent’s friendly message that it is trying again should correspond to a recorded recovery decision in the application.'),
    p('Let a cancellation leave an honest outcome', 'If the user cancels after submission, stop scheduling new work and request cancellation of any supported in-flight operation. The receiver may already have committed the effect. Preserve its operation identity and reconcile the final state before reporting that nothing happened.\n\nFor a workflow with several external effects, recovery may involve a compensating action such as cancelling a created appointment. That compensation is a separate authorised operation with its own possible failure. It does not erase the fact that the original effect occurred. Make partial outcomes visible to the person responsible for the request.', null, 'The next lesson will keep budget reservations for unresolved work rather than pretending a cancelled caller immediately receives its resources back.'),
    p('Trip the retry loop with a completed write', 'Begin with the missing-reply case whose service supports a stable key. The recovery rule can permit another delivery within the deadline. Then load the completed receipt. The same construction should return its stored work-order ID immediately.\n\nChange the payload under that key and check that the result becomes a conflict. Finally, remove the idempotency guarantee and leave the result unknown. Time remaining is no longer enough to justify another write. These cases test different reasons for stopping, so a single retry-until-success loop cannot satisfy them.', null, 'The result of this lesson is a recovery decision. Executing that decision still requires the live service contract and current authorisation checks.'),
  ],
  checkpoint: [q('Botie submits a write. The caller times out. The service does not promise idempotency and its status cannot currently be verified.', 'What should the application preserve?', ['An ambiguous outcome requiring reconciliation', 'A guarantee that the write failed', 'A fresh write with a new key'], 0, 'The missing reply does not tell us whether the effect happened. A new write can duplicate it.'), tf('A service receipt binds key R7-1 to inspection of P7. A later request uses R7-1 for P9.', 'Rejecting the changed payload preserves the original operation identity.', true, 'One key cannot safely name two different approved actions.')],
  quiz: [q('One attempt has started. max_attempts is 3. Current time is 1000 ms, chosen delay is 200 ms, timeout is 500 ms, and deadline is 1600 ms.', 'What does the scheduling check require?', ['Stop because the full next attempt does not fit', 'Retry because fewer than three attempts started', 'Ignore the timeout when checking the deadline'], 0, 'The delay and full timeout must fit the remaining window. The attempt allowance alone is insufficient.'), tf('The client cancelled its local task after the work-order service accepted the write.', 'Local cancellation proves that the work order was rolled back.', false, 'The receiver’s effect can outlive the caller. Its final outcome needs reconciliation.')],
  practice: [challenge('Which recovery action can Botie safely take next?', ["A timeout does not tell us whether a write happened. Look for the receiving service’s record of the operation before deciding whether another attempt is safe. Write next_action(command, receipts, outcome, schedule, state), returning a dictionary with route, delay_ms and result. Match a receipt by command.key and compare the complete payload. A conflict returns \"reject changed payload\". A matching completed receipt returns \"return stored result\" and its result; pending returns \"query operation status\". Otherwise success returns \"done\", permanent returns \"repair request\", and a write without receiver-enforced idempotency returns \"reconcile outcome\".","For other transient or unknown outcomes, calculate capped full-jitter delay as shown in Part 6. Permit \"retry same operation key\" only when attempts is below max_attempts, now_ms is before deadline_ms, and delay plus timeout fits. Otherwise return \"stop at run limit\". Non-retry routes have delay_ms 0; result is None except for stored completion. Inputs use the displayed dictionary fields. Each completed receipt must include result, which may explicitly be None. Compare nested payload values with JSON type semantics: True is different from 1, while numeric 1 and 1.0 match. Reject missing or malformed fields, duplicate receipt keys, negative integer counters, zero timeout, and jitter outside [0,1] with ValueError. Do not mutate inputs. This exercise makes no network calls.","Print the recovery dictionary for the supplied request after an unknown outcome."], 'def next_action(command, receipts, outcome, schedule, state):\n    pass\n\ncommand = {"key":"R9-inspect-1", "payload":{"asset":"P9","operation":"inspect"}, "effect":"write", "idempotent":True}\nschedule = {"base_ms":300,"cap_ms":1200,"jitter_fraction":0.5,"timeout_ms":400,"max_attempts":4}\nstate = {"attempts":2,"now_ms":1000,"deadline_ms":2000}\nprint(next_action(command, [], "unknown", schedule, state))', retrySolution, "{'route': 'retry same operation key', 'delay_ms': 300, 'result': None}", ["Match the operation key and complete payload before looking at retry timing. A completed matching receipt supplies the earlier result; a changed payload is a conflict.","An uncertain write needs a receiver-enforced rule that repeats one intent under one key. Extra time alone cannot make an unsafe duplicate acceptable.","For work that may be retried, keep the jittered delay and per-attempt timeout inside the remaining deadline. Delay is not additional execution time that can be ignored."], [['A bounded retry retains the operation identity', 'assert next_action(command, [], "unknown", schedule, state) == {"route":"retry same operation key","delay_ms":300,"result":None}'], ['Completed receipt and payload conflict', 'receipt = {"key":command["key"],"payload":dict(command["payload"]),"status":"completed","result":"WO-29"}\nassert next_action(command,[receipt],"unknown",schedule,state)["result"] == "WO-29"\nchanged = {**command,"payload":{"asset":"P8","operation":"inspect"}}\nassert next_action(changed,[receipt],"unknown",schedule,state)["route"] == "reject changed payload"'], ['Payload type changes and missing stored results', 'typed = {**command,"payload":{"flags":[True]}}\nreceipt = {"key":command["key"],"payload":{"flags":[1]},"status":"completed","result":"WO-typed"}\nassert next_action(typed,[receipt],"unknown",schedule,state)["route"] == "reject changed payload"\ntry:\n    next_action(command,[{"key":command["key"],"payload":command["payload"],"status":"completed"}],"unknown",schedule,state)\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("Completed receipt needs its stored result")'], ['Pending, permanent and unsafe writes', 'pending = {"key":command["key"],"payload":command["payload"],"status":"pending"}\nassert next_action(command,[pending],"unknown",schedule,state)["route"] == "query operation status"\nassert next_action(command,[],"permanent",schedule,state)["route"] == "repair request"\nassert next_action({**command,"idempotent":False},[],"unknown",schedule,state)["route"] == "reconcile outcome"'], ['Deadline boundary and exhausted attempts', 'assert next_action(command,[],"unknown",schedule,{**state,"deadline_ms":1700})["route"] == "retry same operation key"\nassert next_action(command,[],"unknown",schedule,{**state,"deadline_ms":1699})["route"] == "stop at run limit"\nassert next_action(command,[],"unknown",schedule,{**state,"attempts":4})["route"] == "stop at run limit"'], ['Invalid inputs remain errors', 'for bad in [{**schedule,"timeout_ms":0},{**schedule,"jitter_fraction":1.1},{**schedule,"max_attempts":True}]:\n    try:\n        next_action(command,[],"unknown",bad,state)\n    except ValueError:\n        pass\n    else:\n        raise AssertionError("Invalid retry settings were accepted")']])],
  build: build('Recover the inspection request without duplicating it', 'Botie lost the reply to a work-order request. The service may already know the outcome.', 'Look up the operation receipt. On another branch, classify retry safety from the operation and observed outcome. Calculate whether a delayed attempt fits the run limits, then combine those decisions into the recovery action.', { command: 'Intended operation and receiver contract', receipts: 'Authoritative service receipt snapshot', outcome: 'Observed result of the last attempt', schedule: 'Backoff and per-attempt limits', state: 'Attempts already started and run clock' }, [sample('No receipt yet, with an idempotent receiver', { command: operation, receipts: [], outcome: 'unknown', schedule: retrySchedule, state: retryClock }, recovery('retry same operation key', 100)), sample('The first write completed despite the lost reply', { command: operation, receipts: [{ key: operation.key, payload: operation.payload, status: 'completed', result: 'WO-41' }], outcome: 'unknown', schedule: retrySchedule, state: retryClock }, recovery('return stored result', 0, 'WO-41')), sample('The operation was changed under the old key', { command: { ...operation, payload: { asset: 'P9', operation: 'inspect' } }, receipts: [{ key: operation.key, payload: operation.payload, status: 'completed', result: 'WO-41' }], outcome: 'unknown', schedule: retrySchedule, state: retryClock }, recovery('reject changed payload')), sample('There is no guarantee against duplicate effects', { command: { ...operation, idempotent: false }, receipts: [], outcome: 'unknown', schedule: retrySchedule, state: retryClock }, recovery('reconcile outcome')), sample('The next timeout would cross the deadline', { command: operation, receipts: [], outcome: 'transient', schedule: retrySchedule, state: { ...retryClock, deadline_ms: 1500 } }, recovery('stop at run limit'))], op('arRetryRoute', op('arReceiptLookup', s('command'), s('receipts')), op('arRetrySafety', s('command'), s('outcome')), op('arRetryWindow', s('schedule'), s('state'))), 'The receiver’s stored outcome can resolve the problem without another effect. Safety and timing must both permit a retry when no receipt resolves it.', 'The ledger is a supplied snapshot, not a distributed database. No service is called and no exactly-once execution guarantee is claimed.', ['Build the receipt branch first. It can reveal that the job already exists.', 'Keep the safety and timing branches separate. A remaining attempt cannot make a non-idempotent write safe.']),
});

const limits = { tokens: 1000, cost_units: 20, model_requests: 4, tool_calls: 4 };
const used = { tokens: 200, cost_units: 4, model_requests: 1, tool_calls: 1 };
const reserved = { tokens: 300, cost_units: 6, model_requests: 1, tool_calls: 1 };
const reserve = (tokens, cost_units, model_requests, tool_calls) => ({ tokens, cost_units, model_requests, tool_calls });
const calls = [{ id: 'manual-summary', input_tokens: 120, timeout_ms: 600, reserve: reserve(300, 6, 1, 0) }, { id: 'fault-comparison', input_tokens: 150, timeout_ms: 600, reserve: reserve(300, 6, 1, 0) }];
const control = { cancelled: false, circuit: 'closed', probe_granted: false };
const clock = { now_ms: 1000, deadline_ms: 2000, max_input_tokens: 400 };
const admitted = { accepted: ['manual-summary'], rejected: [{ id: 'fault-comparison', reason: 'resource budget' }], remaining: reserve(200, 4, 1, 2) };
const budgetSolution = `def reserve_calls(proposals, limits, used, reserved, control, clock):
    fields = ("tokens", "cost_units", "model_requests", "tool_calls")
    def whole(value):
        return type(value) is int and value >= 0
    def amounts(value):
        if not isinstance(value, dict) or any(not whole(value.get(k)) for k in fields):
            raise ValueError("Invalid resource amounts")
        return {k:value[k] for k in fields}
    limits, used, reserved = (amounts(v) for v in (limits, used, reserved))
    remaining = {k:limits[k]-used[k]-reserved[k] for k in fields}
    if any(v < 0 for v in remaining.values()):
        raise ValueError("Reconcile an overdrawn ledger before admitting work")
    if (not isinstance(control, dict) or type(control.get("cancelled")) is not bool
            or control.get("circuit") not in ("closed", "open", "half-open")
            or type(control.get("probe_granted")) is not bool):
        raise ValueError("Invalid control state")
    if not isinstance(clock, dict) or any(not whole(clock.get(k)) for k in
            ("now_ms", "deadline_ms", "max_input_tokens")):
        raise ValueError("Invalid clock or context cap")
    if not isinstance(proposals, list):
        raise ValueError("Proposals must be a list")
    accepted, rejected, ids = [], [], set()
    for proposal in proposals:
        if not isinstance(proposal, dict):
            raise ValueError("Proposal must be a record")
        ident = proposal.get("id")
        if not isinstance(ident, str) or not ident.strip() or ident in ids:
            raise ValueError("Use unique nonempty call IDs")
        ids.add(ident)
        need = amounts(proposal.get("reserve"))
        duration, context = proposal.get("timeout_ms"), proposal.get("input_tokens")
        if not whole(duration) or duration == 0 or not whole(context) or need["tokens"] < context:
            raise ValueError("Invalid call timeout or input reservation")
        reason = None
        if control["cancelled"]:
            reason = "cancelled"
        elif control["circuit"] == "open" or (control["circuit"] == "half-open" and not control["probe_granted"]):
            reason = "circuit unavailable"
        elif control["circuit"] == "half-open" and accepted:
            reason = "probe slot used"
        elif context > clock["max_input_tokens"]:
            reason = "request too large"
        elif clock["now_ms"] >= clock["deadline_ms"] or clock["now_ms"] + duration > clock["deadline_ms"]:
            reason = "deadline"
        elif any(need[k] > remaining[k] for k in fields):
            reason = "resource budget"
        if reason is None:
            accepted.append(ident)
            for key in fields:
                remaining[key] -= need[key]
        else:
            rejected.append({"id":ident,"reason":reason})
    return {"accepted":accepted,"rejected":rejected,"remaining":remaining}

limits = {"tokens":900,"cost_units":18,"model_requests":3,"tool_calls":3}
used = {"tokens":100,"cost_units":2,"model_requests":1,"tool_calls":0}
reserved = {"tokens":200,"cost_units":4,"model_requests":0,"tool_calls":1}
proposals = [
    {"id":"manual", "input_tokens":100, "timeout_ms":400, "reserve":{"tokens":400,"cost_units":8,"model_requests":1,"tool_calls":0}},
    {"id":"history", "input_tokens":100, "timeout_ms":400, "reserve":{"tokens":300,"cost_units":6,"model_requests":1,"tool_calls":0}},
]
control = {"cancelled":False,"circuit":"closed","probe_granted":False}
clock = {"now_ms":100,"deadline_ms":1000,"max_input_tokens":300}
print(reserve_calls(proposals, limits, used, reserved, control, clock))`;

const budgets = lesson({
  id: 'agent-resource-budgets', title: 'Can Two of Botie’s Calls Spend the Same Remaining Budget?', topic: 'Keeping an Agent Run Under Control',
  blurb: 'Two proposed lookups each appear affordable until they start together. Reserve shared resources before dispatch and keep the whole run within its operating limits.',
  openingTitle: 'Both Calls Saw Enough Budget, and Together They Spent Too Much',
  opening: ['Botie wants to summarise a manual and compare it with the repair history. The application checks both proposals against the same remaining allowance. Each fits on its own, so both begin. Their combined work exceeds the allowance.', 'Checking the balance was only part of the job. We also needed to reserve the resources when admitting each call. We will build that decision, then see what changes when the user cancels, a dependency starts failing, or the next request cannot finish before the deadline.'],
  prerequisites: [before('Retries and side effects', 'agent-retries-and-effects'), before('LangChain execution limits', 'agent-langchain')],
  history: history('An Agent Run Inherits the Resource Problems of a Service', [source('Microsoft Azure Architecture Center: Circuit Breaker pattern', 'https://learn.microsoft.com/en-us/azure/architecture/patterns/circuit-breaker'), source('gRPC: Deadlines and cancellation', 'https://grpc.io/docs/guides/deadlines/'), source('Pydantic AI: Usage limits and cancellation', 'https://pydantic.dev/docs/ai/core-concepts/agent/#usage-limits')], 'Services already needed ways to stop failed dependencies from consuming every available worker. Circuit breakers record a dependency’s health and temporarily prevent new calls when repeated failures make more work unhelpful. The pattern belongs to distributed-service design; adding a model-controlled loop makes its resource consequences easier to overlook.', 'A model can propose more work than the application can afford to execute. Current agent libraries expose run limits, but their counters and enforcement moments differ. Our lesson uses an explicit reservation ledger so the reader can inspect what was spent, what is still in flight, and what another call would require.'),
  reading: { experimentTitle: 'Reserve work before allowing parallel calls', experimentIntro: 'Subtract settled usage and in-flight reservations first. Check cancellation and circuit state on a separate branch, then admit calls in the declared queue order.', connectionTitle: 'A proposed call still needs an execution slot', practiceTitle: 'Practice. Reserve a batch of proposed calls', outputLabel: 'Admitted calls and remaining allowance', exampleNote: 'All amounts are invented. Cost units are integer accounting units, not provider prices.' },
  intuition: [table('The allowance has three different states', 'The application must count work that started but has not yet reported final usage.', ['Token allowance', 'Meaning', 'Amount'], [['Limit', 'Maximum reserved or settled work for this run', '1000'], ['Settled usage', 'Usage already reported by completed work', '200'], ['Still reserved', 'An earlier call is in flight', '300'], ['Available to admit', 'What remains for new reservations', '500']], 'A reservation represents a bound used by the admission policy. Real usage is reconciled when the operation ends.'), flow('Reserve before the next proposal reads the balance', 'Both proposed calls need a reservation of 300 tokens. Queue order is deliberate in this fixture.', [['Manual summary', 'Fits the available 500; reserve 300'], ['Updated allowance', '200 remains available'], ['Fault comparison', 'Needs 300; do not dispatch yet']], 'A real shared ledger needs an atomic check-and-reserve operation. Two workers cannot safely check separate stale copies.')],
  technicalPart: 5, checkpointAfter: 4,
  parts: [
    p('Name the work that each limit counts', 'A model request is one interaction with a provider, but an agent framework may count a model turn differently from transport attempts. A tool proposal is a request to use a capability; a tool execution is the actual work performed by its handler. Decide whether your operational counters count attempts, successes or both.\n\nA tokenizer splits the text into pieces the model processes; those pieces are tokens. Count the pieces sent in and the pieces generated separately. Money depends on prices and provider accounting, so equal token totals can have different costs. Elapsed time measures what the user waits for. These quantities cannot substitute for one another. The workshop carries separate tokens, cost_units, model_requests and tool_calls fields, with a wall-clock deadline checked separately.', null, 'Document counter semantics at the boundary that enforces them. A limit whose name is ambiguous will be hard to test.'),
    p('Keep one request small enough to send', 'A run can stay below its total allowance while one request exceeds the model’s context window or your application’s input-size limit. Measure the request after assembling its instructions, evidence and conversation state. Reserve room for the response according to the provider’s actual context rules.\n\nThe workshop supplies input_tokens and checks it against max_input_tokens. Its token reservation includes that input plus a chosen output allowance. This is a teaching contract, so a reservation smaller than the input is rejected as malformed. Real systems need a tokenizer or provider counting interface appropriate to the model, including any special messages and tool definitions.', null, 'A cumulative token cap and a per-request context cap protect different boundaries.'),
    p('Count work still in flight', 'Settled usage records operations whose accounting has arrived. A reservation records work already admitted whose final usage is not known. Subtract both when deciding what remains.\n\nIf an operation finishes below its reserved bound, move actual usage to the settled ledger and release only the unused remainder. If accounting is missing, keep an unresolved entry and reconcile it. Treating missing usage as zero creates fictional capacity. Where provider behaviour can exceed an estimate, choose conservative limits and enforce output caps where supported. Application reservations are only as reliable as their bounds and the accounting contract.', 'available = limit - settled_usage - in_flight_reservations', 'Never subtract a reservation from one run and charge its result to an unrelated run. Keep the request and operation identities with both entries.'),
    p('The second proposal must see the first reservation', 'Our two calls each request 300 tokens. The shared remainder is 500. Checking them independently against that initial value admits too much work. Checking the first, reserving it, then checking the second produces a different outcome.\n\nWe use queue order as a transparent admission policy. Other schedulers may prioritise urgent work or maximise useful work under a budget, but they still need a shared atomic reservation step. In a multi-worker service this commonly belongs in a transaction or another concurrency-safe store. Our single-process dictionary calculation only demonstrates the policy.', null, 'A reservation is an execution decision made by the application. The model’s belief that a call is affordable does not reserve anything.'),
    p('Represent each proposed call as an inspectable record', 'Each proposal has an id, input_tokens, timeout_ms and a reserve dictionary. The reserve dictionary names the same four resources as the run limits. A list preserves the queue order. A dictionary stores the remaining amount for each named resource, so tokens cannot accidentally be compared with tool calls.\n\nThe admission function validates every proposal, including one it will later refuse. It returns accepted IDs, rejected IDs with reasons, and the remaining budget. It does not perform network work or mutate the input ledger. That separation makes a test able to inspect the decision before any actual expense or effect occurs.', null, 'The caller must commit the returned reservations atomically before dispatching accepted calls.', [example('Subtract a reservation on a copy of the ledger', 'A dictionary copy keeps the supplied starting allowance intact while we inspect one proposed reservation.', 'available = {"tokens":700, "cost_units":14}\nrequest = {"tokens":250, "cost_units":5}\nremaining = dict(available)\nif all(request[key] <= remaining[key] for key in remaining):\n    for key in remaining:\n        remaining[key] -= request[key]\nprint(remaining)\nprint(available)', "{'tokens': 450, 'cost_units': 9}\n{'tokens': 700, 'cost_units': 14}", 'The copied result shows the proposal’s effect. The original record remains available for a transaction or a failed-decision comparison.')]),
    p('Carry the run deadline into every branch', 'Parallel calls spend resources at the same time. Their elapsed durations do not simply add, but each must respect the run’s remaining deadline. The fixture admits a call only if its full timeout fits before deadline_ms. It uses a shared now_ms snapshot because it is making one batch decision.\n\nA live dispatcher must recheck remaining time immediately before each launch. Waiting in a queue consumes the same deadline. Downstream operations need the remaining budget rather than a new full timeout at every hop. Reserve time for combining results and returning a response, especially if the calls are only an intermediate stage.', null, 'The timeout is a bound on local waiting, not proof that a remote effect will be undone when the clock expires.'),
    p('Cancellation stops new work before it frees old work', 'When the user cancels, stop admitting proposals and signal cancellation to supported in-flight operations. Keep each in-flight reservation until the operation’s final usage or an authoritative cancellation outcome is known. A closed local stream may still leave provider work running or an external write committed.\n\nThe workshop’s cancelled flag blocks the batch and leaves its supplied reservations in place. It does not simulate a remote cancellation protocol. A production UI should distinguish requested cancellation, confirmed cancellation, and an unresolved effect. Partial output also needs a clear status so it is not mistaken for a completed answer.', null, 'Returning early to the user and stopping all downstream work are separate events.'),
    p('Stop feeding a failing dependency', 'A circuit breaker watches failures associated with a dependency. In its closed state, calls can proceed subject to other limits. When the configured failure policy opens the circuit, new calls fail promptly rather than repeatedly spending the request budget on the same unavailable service.\n\nAfter a recovery interval, a half-open state can allow a limited probe. A successful probe can support closing the circuit; another failure can reopen it. Our fixture receives the current state and an application-granted probe slot. It admits at most one proposal while half-open. It does not compute failure windows or recovery transitions, which need service-specific policy and tests.', null, 'An open circuit should describe the dependency that is failing. It should not silently turn every unrelated tool off.'),
    p('Read the library’s limit contract before relying on its name', 'Pydantic AI documents usage limits for requests, tool calls, tokens and cost. Its current tool_calls_limit counts successful tool invocations. Its request_limit counts model responses acted on by the agent loop, rather than every provider transport attempt. Provider retries and some continuation or fallback requests can therefore make transport activity differ from the turn count.\n\nThe enforcement moment matters too. Output-token and cost checks can occur after a response, and cancelled-stream usage may be incomplete. These controls do not all provide a pre-dispatch spending guarantee. Read the installed version’s documentation and test the cases your application relies on. Add application reservations or provider-side limits where the requirement calls for them. Keep unknown prices or usage visible as unknown.', null, 'The workshop’s queue policy is our own teaching design. It does not claim to reproduce a particular framework’s scheduling policy.'),
    p('Use limits at more than one scope', 'A per-run allowance protects one request. It does not stop thousands of permitted requests from exhausting a shared provider quota. A service may also need per-user rate limits, organisation spend controls, concurrency limits, and a bounded queue. Decide which boundary owns each limit.\n\nA queue is a promise of future work. Bound it and provide a clear overload response instead of accepting an unlimited backlog. Reserve capacity for essential recovery and status work where appropriate. Otherwise an exhausted task budget might prevent the very reconciliation needed to discover whether a write completed.', null, 'Fallbacks need permissions and accounting too. Switching providers or launching a helper agent should not reset the original run’s allowance.'),
    p('Test contention, cancellation and recovery as different cases', 'The first fixture exposes two proposals competing for one remaining allowance. The next gives the second call enough room by changing the existing reservation; the same construction should then admit both. A cancelled run must admit neither, regardless of its apparent budget.\n\nThe half-open fixture tests a different rule: only one probe can run even when resources are plentiful. Additional cases isolate the context cap and the deadline. Keep refusal reasons visible so a learner can explain which boundary acted. When a real service refuses work, those same reasons help distinguish expected limits from faulty accounting.', null, 'The next observability lessons will follow these decisions through traces and outcomes instead of reducing every stopped run to one generic error.'),
  ],
  checkpoint: [q('Token limit is 1000. Settled usage is 200. In-flight reservations total 300. Two new calls each request 300 tokens, and all other limits permit them. Queue order is A then B.', 'What should the shared reservation policy admit?', ['A only', 'Both because each fits the initial remainder', 'Neither because an earlier call is in flight'], 0, 'A consumes part of the shared remainder before B is checked. Existing in-flight work does not block everything, but it must stay counted.'), tf('A run has a large total token allowance. One assembled request exceeds its separate per-request input limit.', 'The per-request check should still refuse that request.', true, 'A cumulative run allowance does not establish that one request fits its context boundary.')],
  quiz: [q('The dependency circuit is half-open, a single probe slot has been granted, and two proposals satisfy every resource and time limit.', 'What does this lesson’s admission policy allow?', ['One probe in queue order', 'Both because the resource budget is sufficient', 'Unlimited calls until a failure occurs'], 0, 'The probe allowance is an independent concurrency decision. The second proposal must wait for the probe policy’s next decision.'), tf('The caller cancels a model stream. The provider has not confirmed its final usage.', 'Immediately releasing the entire reservation is supported by the information available.', false, 'The caller’s cancellation does not establish final remote usage. Keep the unresolved reservation until accounting can be reconciled.')],
  practice: [challenge('Which proposed calls can share the remaining allowance?', ["Two queued calls can each look affordable while promising to spend the same remaining tokens. Reserve the first call’s resources before deciding on the next one. Write reserve_calls(proposals, limits, used, reserved, control, clock). Subtract used and reserved from limits for tokens, cost_units, model_requests and tool_calls. Each is a nonnegative integer and booleans are invalid. An overdrawn ledger raises ValueError. Process proposals in list order without mutating inputs.","Each proposal has a unique nonblank id, nonnegative input_tokens, positive timeout_ms, and a reserve dictionary with those four resource fields. Reserved tokens must cover input_tokens. Validate all input records. control contains boolean cancelled, circuit (closed, open or half-open), and boolean probe_granted. clock contains nonnegative integer now_ms, deadline_ms and max_input_tokens.","Refusal precedence is cancelled; circuit unavailable for open or ungranted half-open; probe slot used after one accepted half-open call; request too large; deadline; resource budget. An accepted call reserves every resource before the next call is checked. Return {\"accepted\": IDs, \"rejected\": [{\"id\": ID, \"reason\": reason}], \"remaining\": resource dictionary}. Reject malformed input with ValueError. Print the supplied example’s result."], 'def reserve_calls(proposals, limits, used, reserved, control, clock):\n    pass\n\nlimits = {"tokens":900,"cost_units":18,"model_requests":3,"tool_calls":3}\nused = {"tokens":100,"cost_units":2,"model_requests":1,"tool_calls":0}\nreserved = {"tokens":200,"cost_units":4,"model_requests":0,"tool_calls":1}\nproposals = [\n    {"id":"manual", "input_tokens":100, "timeout_ms":400, "reserve":{"tokens":400,"cost_units":8,"model_requests":1,"tool_calls":0}},\n    {"id":"history", "input_tokens":100, "timeout_ms":400, "reserve":{"tokens":300,"cost_units":6,"model_requests":1,"tool_calls":0}},\n]\ncontrol = {"cancelled":False,"circuit":"closed","probe_granted":False}\nclock = {"now_ms":100,"deadline_ms":1000,"max_input_tokens":300}\nprint(reserve_calls(proposals, limits, used, reserved, control, clock))', budgetSolution, "{'accepted': ['manual'], 'rejected': [{'id': 'history', 'reason': 'resource budget'}], 'remaining': {'tokens': 200, 'cost_units': 4, 'model_requests': 1, 'tool_calls': 2}}", ["Calls already in flight occupy budget even before their final usage arrives. Subtract both settled usage and outstanding reservations into a new resource dictionary.","Validate every proposal before dispatch decisions, then process proposals in their supplied order. An accepted reservation reduces the remainder used by the following proposal.","Keep the declared refusal order. Cancellation and dependency health can stop work even when the resource ledger has room; a half-open circuit permits only its granted probe.","A call also needs a permitted input size and enough time for its timeout. Those checks do not follow automatically from a positive token balance."], [['Two calls cannot spend the same remainder', 'answer = reserve_calls(proposals, limits, used, reserved, control, clock)\nassert answer["accepted"] == ["manual"]\nassert answer["remaining"] == {"tokens":200,"cost_units":4,"model_requests":1,"tool_calls":2}'], ['Cancellation and circuit refusal', 'for update, reason in [({"cancelled":True},"cancelled"),({"circuit":"open"},"circuit unavailable")]:\n    answer = reserve_calls(proposals,limits,used,reserved,{**control,**update},clock)\n    assert answer["accepted"] == []\n    assert all(row["reason"] == reason for row in answer["rejected"])'], ['Half-open allows one probe despite spare capacity', 'room = {k:10000 for k in limits}\nzero = {k:0 for k in limits}\nanswer = reserve_calls(proposals,room,zero,zero,{**control,"circuit":"half-open","probe_granted":True},clock)\nassert answer["accepted"] == ["manual"]\nassert answer["rejected"] == [{"id":"history","reason":"probe slot used"}]'], ['Context and deadline apply separately', 'assert reserve_calls(proposals,limits,used,reserved,control,{**clock,"max_input_tokens":99})["rejected"][0]["reason"] == "request too large"\nassert reserve_calls(proposals,limits,used,reserved,control,{**clock,"deadline_ms":499})["rejected"][0]["reason"] == "deadline"\nassert reserve_calls(proposals,limits,used,reserved,control,{**clock,"deadline_ms":500})["accepted"] == ["manual"]'], ['No mutation and invalid ledger rejection', 'import copy\nsnapshot = copy.deepcopy((proposals,limits,used,reserved,control,clock))\nreserve_calls(proposals,limits,used,reserved,control,clock)\nassert snapshot == (proposals,limits,used,reserved,control,clock)\ntry:\n    reserve_calls(proposals,{**limits,"tokens":1},used,reserved,control,clock)\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("Overdrawn budget must be rejected")']])],
  build: build('Reserve the next maintenance lookups', 'Two proposed calls compete with an earlier in-flight call for one run’s allowance.', 'Subtract settled usage and current reservations. Separately inspect cancellation and circuit state. Feed those results, the call queue and deadline information into the reservation step. Return the accepted calls, reasons for refusal and remaining budget.', { proposals: 'Proposed calls in queue order', limits: 'Total run allowances', used: 'Settled usage', reserved: 'Earlier work still in flight', control: 'Cancellation and dependency circuit', clock: 'Run clock and per-request context cap' }, [sample('Two calls compete for the same remainder', { proposals: calls, limits, used, reserved, control, clock }, admitted), sample('The earlier call has a smaller reservation', { proposals: calls, limits, used, reserved: reserve(100, 2, 1, 1), control, clock }, { accepted: ['manual-summary', 'fault-comparison'], rejected: [], remaining: reserve(100, 2, 0, 2) }), sample('The user cancels before dispatch', { proposals: calls, limits, used, reserved, control: { ...control, cancelled: true }, clock }, { accepted: [], rejected: calls.map(call => ({ id: call.id, reason: 'cancelled' })), remaining: reserve(500, 10, 2, 2) }), sample('Only one recovery probe is permitted', { proposals: calls, limits, used, reserved: reserve(0, 0, 0, 0), control: { ...control, circuit: 'half-open', probe_granted: true }, clock }, { accepted: ['manual-summary'], rejected: [{ id: 'fault-comparison', reason: 'probe slot used' }], remaining: reserve(500, 10, 2, 3) }), sample('The context cap is smaller than either input', { proposals: calls, limits, used, reserved, control, clock: { ...clock, max_input_tokens: 100 } }, { accepted: [], rejected: calls.map(call => ({ id: call.id, reason: 'request too large' })), remaining: reserve(500, 10, 2, 2) })], op('arReserveBatch', s('proposals'), op('arAvailableBudget', s('limits'), s('used'), s('reserved')), op('arDispatchStatus', s('control')), s('clock')), 'The next proposal sees resources already reserved for earlier proposals. Independent cancellation, dependency and request-size checks can still refuse affordable work.', 'This is a deterministic admission snapshot. It does not implement distributed transactions, provider billing, remote cancellation or circuit-state transitions.', ['Build the available-budget branch first. In-flight reservations belong in that subtraction.', 'A half-open circuit has its own probe allowance even if the numeric resource caps have room.']),
});

